Lemma u8_mod : forall (M : mem) a v, L5.u8_at RSEGS M a v -> L5.u8_at RSEGS M a (v mod 256).
Proof.
  intros M a v H. unfold L5.u8_at in *. rewrite H. f_equal. f_equal. apply bv_eq. rewrite !Z_to_bv_unsigned. unfold bv_wrap.
  change (bv_modulus 8) with 256. rewrite Zmod_mod. reflexivity.
Qed.

