Theorem begin_scalar_nested_ok : forall (LBo : list (Z * Z)) (cr : credit) (sp r V S2 kx bx : Z) (g : eghost) (c0 : ectx) (r0 : estate),
  PML.cps_heap L HI PC_BEGIN_SCALAR r sp (16 + NEWLINE_SCR) (LBo ++ g_lbv g) cr
    (fun R M => PML.entry L R M sp r (16 + NEWLINE_SCR) /\ PML.a0 R V /\ enc_inv M V S2 g /\ g_es g = c0 :: r0 /\ g_len g + bs_delta (g_es g) <= CLU /\ PML.img_ro M /\ ecreditU L cr g kx bx /\ objs_enc L sp V S2)
    (fun R M R' M' LB' cr' LBk W => exists (g' : eghost) (d : Z),
        enc_inv M' V S2 g' /\ g_es g' = set_nla c0 :: r0 /\ g_sb g' = g_sb g /\ g_scap g' = g_scap g /\ d = comma c0 + nl (g_es g) /\ g_len g' = g_len g + d /\
        LB' = LBo ++ g_lbv g' /\ LBk = LBo /\ W = W_h V S2 /\ ecreditU L cr' g' kx bx).
Proof.
  intros LBo cr sp r V S2 kx bx g c0 r0. unfold PML.cps_heap.
  intros fx R M model K HH Hmo HKnil Hfp (Hentry & Ha0 & Hinv & Hes & Hroom & Himg & Hcred & Hobjs) Hcont.
  destruct Hentry as (Hra & Hraok & Hsp & Htp & Hstk). destruct Hstk as (S1 & S2' & S3 & S4 & S5).
  unfold NEWLINE_SCR, STRX_SCR, PMS.STR_SCR, PMS.OPNEW_SCR, PML.HEAP_STACK in *.
  pose proof Hobjs as ((OV1 & OV2 & OV3) & (OS1 & OS2 & OS3) & OAP). unfold ENC_SIZE, PML.apart in OV2, OAP.
  pose proof (PmLayout.ly_segs L LAY) as LS. pose proof (PmLayout.ly_img_lo L LAY) as ILO. pose proof (PmLayout.ly_img_hi L LAY) as IHI.
  pose proof (PmLayout.ly_errno L LAY) as LER.
  destruct g as [es0 len0 rep b cb]. cbn [g_es g_len g_rep g_sb g_scap] in *. subst es0.
  destruct c0 as [arr cnt nla0].
  set (dr := depth r0).
  assert (DEP : depth (ECtx arr cnt nla0 :: r0) = dr + 1) by (unfold dr; apply EK2.depth_cons).
  assert (DR0 : 0 <= dr) by (unfold dr, depth; lia).
  unfold bs_delta, comma, nl in Hroom. cbn [ec_count] in Hroom. rewrite DEP in Hroom.
  assert (RM1 : 0 < cnt -> len0 + 2 + (1 + 4 * (dr + 1)) <= CLU).
  { intros Hc0. replace (0 <? cnt) with true in Hroom by (symmetry; apply Z.ltb_lt; exact Hc0). lia. }
  assert (RM0 : cnt = 0 -> len0 + (1 + 4 * (dr + 1)) <= CLU).
  { intros Hc0. replace (0 <? cnt) with false in Hroom by (symmetry; apply Z.ltb_ge; lia). lia. }
  assert (CLU47 : CLU < 2 ^ 47) by (unfold CLU; lia).
  pose proof Hinv as (I1 & I2 & I3 & I4 & I5). cbn [g_es g_len g_rep g_sb g_scap] in I1, I2, I3, I4, I5.
  rewrite DEP in I1, I5. unfold MAX_DEPTH in I5.
  destruct I2 as (ST1 & ST2 & ST3 & ST4 & ST5 & ST6). rewrite DEP in ST2, ST4. unfold O_STACK in ST1, ST2, ST3.
  assert (CB : 32 <= cb <= 32768).
  { destruct ST5 as [(E1 & _)|(k & Hk & E1)]; [lia|]. pose proof (pow2_10 k Hk). lia. }
  assert (LBV : g_lbv (EG (ECtx arr cnt nla0 :: r0) len0 rep b cb) = PML.srep_blocks rep ++ [(b, cb)]).
  { unfold g_lbv, stack_blocks. cbn [g_rep g_sb g_scap]. destruct (Z.eqb_spec cb 0); [lia | reflexivity]. }
  rewrite LBV in HH.
  destruct (hio_wf L SCFG HI HIok _ _ _ _ HH) as (Hwf & _).
  assert (INB : In (b, cb) (LBo ++ PML.srep_blocks rep ++ [(b, cb)])) by (apply in_or_app; right; apply in_or_app; right; left; reflexivity).
  destruct (Hwf _ INB) as ((BR1 & BR2 & BR3 & BR4 & BR5) & _ & _). cbn [fst snd] in BR1, BR2, BR3, BR4, BR5.
  assert (CHI : hl_ceil L <= 2 ^ 47) by (unfold hl_ceil; lia).
  assert (CLO : 0x7fff7f800000 <= hl_ceil L) by (unfold hl_ceil; lia).
  assert (HC : ctx_at M (b + 32 * dr) (ECtx arr cnt nla0)).
  { assert (Hlt : (length r0 < length (ECtx arr cnt nla0 :: r0))%nat) by (cbn [length]; lia).
    pose proof (ST6 (length r0) Hlt) as H. cbn [length] in H. replace (S (length r0) - 1 - length r0)%nat with 0%nat in H by lia. exact H. }
  destruct HC as (HC1 & HC2 & HC3 & HC4 & HC5 & HC6). cbn [ec_arr ec_count ec_nla] in HC1, HC3, HC4, HC5.
  destruct I1 as (H1 & H2 & H3 & (fl & H4 & H4') & H5 & H6 & H7 & H8 & H9 & H10 & H11 & H12 & H13 & H14 & H15 & H16 & H17 & (en & H18 & H18') & H19 & H20 & H21 & H22 & (dp & H23) &
                  H24 & H25 & H26 & H27 & (H28 & H28') & H29).
  unfold O_SINK, O_COLUMN, O_COMMA in *.
  destruct (PB.bytes_of_defined M 1 (b + 32 * dr + 5) ltac:(lia) ltac:(lia)) as (ibs & Hibl & Hibs).
  { intros j Hj. replace (b + 32 * dr + 5 + j) with (b + 32 * dr + (5 + j)) by lia. apply HC6. lia. }
  destruct ibs as [|ib [|]]; try discriminate Hibl.
  pose proof (Hibs 0%nat ltac:(cbn [length]; lia)) as HIB. cbn [nth] in HIB. replace (b + 32 * dr + 5 + Z.of_nat 0) with (b + 32 * dr + 5) in HIB by lia.
  pose proof (u8_mod M _ _ HIB) as HIB'.
  destruct (EAK.u64_of_defined M (V + 296) H25) as (col & Hcol0 & Hcol).
  set (E0 := Env (reg_ev R (fun v => Z_to_bv 64 (nth (v - 32) [S2; dr + 1; b; cb; cnt; col; PML.b2z arr; ib mod 256; PML.b2z nla0] 0))) (fun _ => [])).
