      pose proof (PB2.kword8_elim E' M' _ _ (b + 32 * dr + 6) (PB.has_ok E' M' _ _ HKc Xn)
                    ltac:(transitivity (b + 32 * (dr + 1) + -26); [exact (ESE E' (-26) HagE') | lia])) as HU8.
      assert (HU8' : PML.u8 M' (b + 32 * dr + 6) (PML.b2z true)) by exact HU8.
      assert (DEFC : L5.defined M0c (sp - 8592) 8592) by (rewrite <- SCRV; exact (CH2V.okV_def0 L M LBo sp G.HDECL W M0c OKV)).
      destruct (ETL.tail_leaf L HI HIok LAY GT.NF E0 M0c model (CH2V.LBr LBo eghost gB g1) sp G.HDECL W G.BLS (CredV g1) STKF SCRP NF32 U2 W_OK WRS_OK G.CPS G.TAGS
                  (CH2V.okV_def0 L M LBo sp G.HDECL W M0c OKV) 8592 ltac:(rewrite SCRV; lia) ltac:(unfold hl_ceil; lia) DEFC R EV heap_ok3
                  i c kk ps PC_NEW_LINE IL Xtb E R1 M1 m1 E' R' M' HAt HAmb Hag HLF) as (HRP & KEEP & HP & HA' & _).
      destruct (STRETCH g1 M0c i c kk ps _ E R1 M1 m1 E' R' M' true IL HAt OKV HAmb HX Hag HLF HU8') as (HINV & _ & HIMG).
      destruct (HEAP g1 M0c i E M' m1 Xi XB HA') as [_ (cr1 & HH1 & HCr1)].
      pose proof HA' as (Hmo1 & Hbv1 & _).
      destruct HX as (_ & X2 & X3 & X4 & X5 & X6).
      set (g2 := EG (ECtx arr cnt true :: r0) (g_len g1) (g_rep g1) b cb).
      assert (HH2 : hi_heap HI (LBo ++ g_lbv g2) cr1 M' (m_vmmaps m1)).
      { apply (CH2V.hi_heap_perm L HI HIok _ _ _ _ _ HH1). unfold g2, g_lbv, stack_blocks. cbn [g_rep g_sb g_scap].
        destruct (Z.eqb_spec cb 0); [lia|]. rewrite app_assoc. apply Permutation_cons_append. }
      assert (HCg2 : ecreditU L cr1 g2 kx bx).
      { unfold CredV, EBU.CredV, ecreditU, kenc, benc in HCr1. unfold g2, ecreditU, kenc, benc. cbn [g_rep g_scap]. rewrite <- X4. exact HCr1. }
      assert (NL2 : nl (g_es g2) = 1 + 4 * (dr + 1)) by (unfold g2, nl; cbn [g_es]; rewrite EK2.depth_cons; reflexivity).
      assert (OFFC : off i = comma (ECtx arr cnt nla0) /\ g_len g1 + nl (g_es g2) <= CLU).
      { rewrite X5, NL2. unfold comma. cbn [ec_count]. destruct i as [|[|i]].
        - pose proof (PB.prove_ok E' M' _ _ HKc Xm) as HK36. cbn [kentry_ok] in HK36. fold (PB.uv E' (EVar 36)) in HK36.
          assert (Q36 : PB.uv E' (EVar 36) = cnt) by (rewrite (PB.uv_agree GT.NF E0 E' (EVar 36) HagE' eq_refl); exact U36).
          assert (C0 : cnt = 0) by lia.
          replace (0 <? cnt) with false by (symmetry; apply Z.ltb_ge; lia). unfold off; cbv beta iota. split; [reflexivity|]. pose proof (RM0 C0). lia.
        - pose proof (X6 eq_refl) as Hc0.
          replace (0 <? cnt) with true by (symmetry; apply Z.ltb_lt; exact Hc0). unfold off; cbv beta iota. split; [reflexivity|]. pose proof (RM1 Hc0). lia.
        - lia. }
      destruct OFFC as [OFF ROOM2].
      assert (HP2 : L5C.hpres L LBo sp 8592 W M M').
      { rewrite <- SCRV. apply (CH2V.hpres_rebase L GT.NF M LBo sp G.HDECL W eghost gB NF32 g1 M0c M' OKV). rewrite SCRV. exact HP. }
      assert (Ga0 : getr R' 10%bv = Z_to_bv 64 V).
      { pose proof (CL.ps_reg_is_sound (hl_segs L) c ps E' R' M1 M' 10 (EVar 10) HLF X10) as G10.
        replace (Z_to_bv 5 (Z.of_nat 10)) with (10%bv : bv 5) in G10 by (apply bv_eq; reflexivity). rewrite G10. cbn [edenot].
        destruct HagE' as [AG _]. rewrite <- AG by (unfold GT.NF; lia). exact V10. }
      rewrite Xps, LS.
      apply (NEWLINE_OK LBo cr1 sp r V S2 kx bx g2 fx' R' M' m1 K HH2 Hmo1 HKnil HFP).
      { split; [split; [rewrite (KEEP 1%bv ltac:(left; reflexivity)); exact Hra | split; [exact Hraok | split; [rewrite (KEEP 2%bv ltac:(right; left; reflexivity)); exact Hsp |
                 split; [rewrite (KEEP 4%bv ltac:(right; right; right; left; reflexivity)); exact Htp|]]]]|].
        - unfold NEWLINE_SCR, STRX_SCR, PMS.STR_SCR, PMS.OPNEW_SCR, PML.HEAP_STACK. split; [exact S1|]. split; [unfold hl_ceil in *; lia|]. split; [lia|]. split; [lia|].
          intros j Hj. replace (sp - (80 + (256 + (16 + 8224))) + j) with (sp - 8592 + (j + 16)) by lia. apply (L5C.hpres_defined _ _ _ _ _ _ _ HP2). lia.
        - split; [exact Ga0|]. split; [exact I|]. split; [exact HINV|]. split; [exact I|]. split; [exact ROOM2|].
          split; [exact HIMG|]. split; [exact HCg2|]. exact Hobjs. }
      intros fx2 R2 M2 model2 LB' cr' LBk Wc HFP2 (g' & d' & P1 & P2 & P3 & P4 & P5 & P6 & P7 & P8 & P9 & P10) HRP2 HPc Hbv2 HH3.
      subst LB' LBk Wc.
      apply (Hcont fx2 R2 M2 model2 (LBo ++ g_lbv g') cr' LBo W HFP2); [| exact (L5.regs_preserved_trans _ _ _ HRP HRP2) | | exact (L5C.model_but_vm_trans _ _ _ Hbv1 Hbv2) | exact HH3].
      * exists g', (comma (ECtx arr cnt nla0) + nl (ECtx arr cnt nla0 :: r0)).
        split; [exact P1|]. split; [rewrite P2; reflexivity|]. split; [rewrite P3; reflexivity|]. split; [rewrite P4; reflexivity|]. split; [reflexivity|].
        split; [rewrite P6, P5, NL2; unfold g2; cbn [g_len]; rewrite X5, OFF; unfold nl; rewrite DEP; lia|].
        split; [reflexivity|]. split; [reflexivity|]. split; [reflexivity|]. exact P10.
      * apply (ETL.hpres_comp L LBo sp 8592 (80 + (256 + (16 + 8224))) W M M' M2); [lia | unfold hl_ceil in *; lia | lia | rewrite LER; lia | lia | exact HP2 | exact HPc].
  - reflexivity.
  - rewrite LS.
    assert (Hds : L5.defined M (sp - 8592) 8592) by (rewrite <- SCRV; exact DEF0).
    assert (WENDE : edenot E0 (EAlu ALU_ADD (EMd M_MUL (ELit 32) (EVar 33)) (EVar 34)) = Z_to_bv 64 (b + 32 * (dr + 1))).
    { apply PB.edenot_of_uv. unfold PB.uv. apply CL5.u_lin; [lin_eval; rw_atoms; lia | lia]. }
    assert (ESE0 : forall o, estart E0 (SA (EAlu ALU_ADD (EMd M_MUL (ELit 32) (EVar 33)) (EVar 34)) o) = b + 32 * (dr + 1) + o)
      by (intros o; apply ESE; apply CC.env_agree_refl).
    split; [exact (regs_ok_id R _ _)|]. unfold know_ok, G.cp0. cbn [CC.cp_know].
    repeat (apply Forall_cons); [.. | apply Forall_nil].
    + eapply CL5.kword64_intro with (A := V + 8) (z := S2); [ev_start | lia | lia | exact V32 | exact H2].
    + eapply CL5.kword64_intro with (A := V + 264) (z := b); [ev_start | lia | lia | exact V34 | exact ST1].
    + eapply CL5.kword64_intro with (A := V + 264 + 8) (z := b + 32 * (dr + 1)); [ev_start | lia | lia | exact WENDE | exact ST2].
    + eapply CL5.kword64_intro with (A := V + 296) (z := col); [ev_start | lia | lia | exact V37 | exact Hcol].
    + eapply CL5.kword64_intro with (A := V + 320) (z := TXT_COMMA); [ev_start | lia | lia | reflexivity | exact H28].
    + eapply CL5.kword64_intro with (A := V + 320 + 8) (z := 2); [ev_start | lia | lia | reflexivity | exact H28'].
    + eapply PB.kword32_intro with (A := b + 32 * dr) (z := PML.b2z arr); [rewrite ESE0; lia | lia | lia | exact V38 | exact HC1].
    + eapply PB2.kword8_intro with (A := b + 32 * dr + 4) (z := 0); [rewrite ESE0; lia | lia | lia | reflexivity | lia | exact HC2].
    + eapply PB2.kword8_intro with (A := b + 32 * dr + 5) (z := ib mod 256);
        [rewrite ESE0; lia | lia | lia | exact V39 | pose proof (Z.mod_pos_bound ib 256 ltac:(lia)); lia | exact HIB'].
    + eapply CL5.kword64_intro with (A := b + 32 * dr + 24) (z := cnt); [rewrite ESE0; lia | lia | lia | exact V36 | exact HC4].
    + eapply PB2.kword8_intro with (A := b + 32 * dr + 6) (z := PML.b2z nla0); [rewrite ESE0; lia | lia | lia | exact V40 | unfold PML.b2z; destruct nla0; lia | exact HC3].
    + e_range.
    + eapply CL5.kwr_intro with (A := b + 32 * dr + 6) (N := 1); [rewrite ESE0; lia | ev_len | lia | lia | lia | ev_def].
    + e_range. + e_range. + e_range. + e_range. + e_align BR3. + e_range. + e_range.
    + e_wr. + e_range. + e_align OV3. + e_range. + e_align OS3.
    + e_unk. + e_unk. + e_wr. + e_range. + e_align S1.
    + e_disj. + e_disj. + e_disj. + e_disj. + e_disj. + e_disj.
  - apply (CH2V.amb3V_intro L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS eghost gB CredV XIv (EG (ECtx arr cnt nla0 :: r0) len0 rep b cb) M 0%nat E0 M model
             (CH2V.okV_refl L M LBo sp G.HDECL W DEF0)).
    split; [|split; [exact Hinv | split; [reflexivity | split; [reflexivity | split; [reflexivity | split; [unfold off; cbn [g_len]; cbv beta iota; lia | intros H0; discriminate H0]]]]]].
    split; [exact Hmo|]. split; [apply L5C.model_but_vm_refl|]. split; [apply CC.env_agree_refl|].
    split; [|split; [reflexivity | intros a _ _ Hd; exact Hd]].
    exists cr. split; [|exact Hcred].
    unfold CH2.cur, CH2V.LBr. rewrite HB0, (DEN E0 (CC.env_agree_refl _ _)). unfold gB, EBU.gB. cbn [g_rep]. rewrite app_nil_r.
    apply (CH2V.hi_heap_perm L HI HIok _ _ _ _ _ HH). rewrite app_assoc. apply Permutation_sym, Permutation_cons_append.
  - exact Hfp.
Qed.
